import clsx from 'clsx';
import React, { useLayoutEffect } from 'react';

import { divPlotLayout } from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useOverlaysEvents } from '../../../../core/hooks/useOverlaysEvents.js';
import { GroupDataPoint } from '../../../../core/types/data-point.js';
import { useOverlaysState } from '../../../hooks/store/selectors.js';
import { useSetResetOverlaysState } from '../../../hooks/store/state-setters.js';
import { useTimeseriesFilteredData } from '../../../hooks/useTimeseriesFilteredData.js';
import { usePinnedAwarePosition } from '../hooks/usePinnedAwarePosition.js';
import { TimeseriesChartDatapoints } from '../TimeseriesChartDatapoints.js';
import { TimeseriesChartTooltip } from '../TimeseriesChartTooltip.js';
import { inspectDatapointsLayout } from '../TimeseriesOverlays.sty.js';
import { TimeseriesClosestPoint } from '../utils/tooltip/find-closest-points.js';

type TimeseriesInspectProps = {
  filteredPoints: TimeseriesClosestPoint[];
  closestPoint: TimeseriesClosestPoint;
  groupedPoints: GroupDataPoint;
};

export const TimeseriesInspect = ({
  filteredPoints,
  closestPoint,
  groupedPoints,
}: TimeseriesInspectProps) => {
  const { data: series } = useTimeseriesFilteredData();
  const { isInChartBounds } = useOverlaysEvents();
  const { visibleTooltip, pinnedTooltip } = useOverlaysState();
  const setResetOverlaysState = useSetResetOverlaysState();
  const mousePosition = usePinnedAwarePosition();

  useLayoutEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setResetOverlaysState();
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  const showDatapoints = isInChartBounds || pinnedTooltip;

  return mousePosition ? (
    <>
      <div className={clsx(divPlotLayout, inspectDatapointsLayout)}>
        {showDatapoints && (
          <TimeseriesChartDatapoints
            closestPoint={pinnedTooltip ? undefined : closestPoint}
            groupedPoints={groupedPoints}
          />
        )}
      </div>
      {filteredPoints.length > 0 && (visibleTooltip || pinnedTooltip) && (
        <TimeseriesChartTooltip
          series={series}
          closestPoint={closestPoint}
          xPoints={filteredPoints}
          groupedPoints={groupedPoints}
        />
      )}
    </>
  ) : null;
};

TimeseriesInspect['displayName'] = 'TimeseriesInspect';
